package app.morphe.extension.newx.postfilter;
import android.app.*;import android.content.*;import android.net.Uri;import android.os.Bundle;import android.view.*;import android.widget.*;import org.json.*;import java.io.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.util.concurrent.*;
import app.morphe.extension.crimera.settings.CustomScreenFragment;
public final class AdvancedFilterFragment extends CustomScreenFragment {
    private static final int IMPORT=7511,EXPORT=7512;
    private static final ExecutorService WORKER=Executors.newSingleThreadExecutor();
    private EditText editor;private TextView count,status;private Spinner mode;private final Map<String,CheckBox> checks=new LinkedHashMap<>();private boolean merge=true;private String exportText;
    @Override public View onCreateView(LayoutInflater inflater,ViewGroup container,Bundle state){Context ctx=getActivity();ScrollView scroll=new ScrollView(ctx);LinearLayout body=new LinearLayout(ctx);body.setOrientation(1);int pad=(int)(16*ctx.getResources().getDisplayMetrics().density);body.setPadding(pad,pad,pad,pad);scroll.addView(body);
        TextView title=new TextView(ctx);title.setText("Advanced Global Keyword Filter");title.setTextSize(21);body.addView(title);
        count=new TextView(ctx);body.addView(count);editor=new EditText(ctx);editor.setGravity(Gravity.TOP);editor.setMinLines(5);editor.setMaxLines(9);editor.setHint("Un mot ou une expression par ligne");editor.setInputType(0x00020001|0x00080000);body.addView(editor,new LinearLayout.LayoutParams(-1,-2));
        mode=new Spinner(ctx);mode.setAdapter(new ArrayAdapter<String>(ctx,android.R.layout.simple_spinner_dropdown_item,new String[]{"Sous-chaîne","Mot entier","Regex RE2 (avancé)"}));body.addView(mode);
        toggle(body,"enabled","Activer le filtre");toggle(body,"strict","Mode strict : masquer si parent/citation absent");toggle(body,"foldAccents","Ignorer les accents (hors regex)");
        toggle(body,"posts","Publications");toggle(body,"authors","Pseudos et noms des auteurs");toggle(body,"bios","Biographies disponibles");toggle(body,"quotes","Propager aux citations");toggle(body,"replies","Propager aux réponses et descendants");toggle(body,"links","Aperçus de liens disponibles");toggle(body,"trends","Tendances");toggle(body,"notifications","Notifications dans X (données disponibles)");toggle(body,"search","Suggestions de recherche");toggle(body,"accounts","Suggestions de comptes");
        button(body,"Enregistrer la liste et les options",v->save());
        button(body,"Importer TXT / CSV / JSON",v->new AlertDialog.Builder(getActivity()).setTitle("Importation").setItems(new String[]{"Fusionner avec la liste affichée","Remplacer la liste affichée"},(d,w)->{merge=w==0;Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE);startActivityForResult(i,IMPORT);}).show());
        button(body,"Exporter la liste affichée en TXT",v->{exportText=editor.getText().toString();Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT).setType("text/plain").addCategory(Intent.CATEGORY_OPENABLE).putExtra(Intent.EXTRA_TITLE,"piko-keywords.txt");startActivityForResult(i,EXPORT);});
        button(body,"Restaurer la configuration initiale Morphe",v->new AlertDialog.Builder(getActivity()).setMessage("Remplacer la configuration locale par celle intégrée lors du patching ?").setNegativeButton("Annuler",null).setPositiveButton("Restaurer",(d,w)->run(()->{AdvancedConfig.reset();return "Configuration initiale restaurée";},true)).show());
        status=new TextView(ctx);status.setText("Les changements s’appliquent aux prochains chargements. Actualise le fil pour les éléments déjà affichés.\n"+AdvancedFilter.diagnostics());body.addView(status);
        try{load();}catch(Exception e){status.setText(e.toString());}return scroll;
    }
    private void toggle(LinearLayout body,String key,String label){CheckBox c=new CheckBox(getActivity());c.setText(label);checks.put(key,c);body.addView(c);}
    private void button(LinearLayout b,String t,View.OnClickListener l){Button v=new Button(getActivity());v.setText(t);v.setOnClickListener(l);b.addView(v);}
    private void load()throws Exception {AdvancedConfig c=AdvancedConfig.get();JSONObject j=c.json();editor.setText(String.join("\n",c.keywords));count.setText(c.keywords.size()+" mots-clés enregistrés");mode.setSelection(c.mode.equals("regex")?2:c.mode.equals("word")?1:0);for(Map.Entry<String,CheckBox> e:checks.entrySet())e.getValue().setChecked(j.optBoolean(e.getKey()));}
    private JSONObject form()throws Exception{JSONObject j=new JSONObject();j.put("keywords",new JSONArray(AdvancedLists.parse(editor.getText().toString(),"txt")));j.put("mode",new String[]{"substring","word","regex"}[mode.getSelectedItemPosition()]);for(Map.Entry<String,CheckBox> e:checks.entrySet())j.put(e.getKey(),e.getValue().isChecked());return j;}
    private void save(){try{JSONObject data=form();run(()->{AdvancedConfig.save(data);return "Enregistré. Actualise le fil pour réévaluer son contenu.";},true);}catch(Exception e){status.setText(e.toString());}}
    private interface Job {String run()throws Exception;}
    private void run(Job job,boolean reload){Activity activity=getActivity();status.setText("Traitement…");WORKER.execute(()->{String msg;boolean ok;try{msg=job.run();ok=true;}catch(Exception e){msg="Erreur : "+e.getMessage();ok=false;}String result=msg;boolean done=ok;activity.runOnUiThread(()->{if(!isAdded())return;try{if(done&&reload)load();status.setText(result);}catch(Exception e){status.setText(e.toString());}});});}
    @Override public void onActivityResult(int request,int result,Intent data){super.onActivityResult(request,result,data);if(result!=Activity.RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();ContentResolver resolver=getActivity().getContentResolver();
        if(request==EXPORT){final String text=exportText;run(()->{try(OutputStream o=resolver.openOutputStream(uri,"wt")){if(o==null)throw new IOException("Fichier inaccessible");o.write(text.getBytes(StandardCharsets.UTF_8));}return "Liste exportée";},false);}
        if(request==IMPORT){final String before=editor.getText().toString();final boolean combine=merge;final Activity activity=getActivity();status.setText("Lecture du fichier…");WORKER.execute(()->{try{String text;try(InputStream i=resolver.openInputStream(uri)){text=AdvancedLists.read(i);}String name="";try(android.database.Cursor cur=resolver.query(uri,new String[]{android.provider.OpenableColumns.DISPLAY_NAME},null,null,null)){if(cur!=null&&cur.moveToFirst())name=cur.getString(0);}
                    List<String> all=new ArrayList<>();if(combine)all.addAll(AdvancedLists.parse(before,"txt"));all.addAll(AdvancedLists.parse(text,name.toLowerCase(Locale.ROOT).endsWith(".csv")?"csv":"txt"));String joined=String.join("\n",all);
                    activity.runOnUiThread(()->{if(isAdded()){editor.setText(joined);status.setText("Liste importée. Appuie sur Enregistrer pour appliquer et dédoublonner.");}});
                }catch(Exception e){activity.runOnUiThread(()->{if(isAdded())status.setText("Import refusé : "+e.getMessage());});}});}
    }
}
